/// `RouteOut` is the callback type for routing `AllocationInstruction` messages.
pub type RouteOut = fn(msg: AllocationInstruction, session_id: SessionID) -> Result<(), MessageRejectErrorEnum>;

/// Route type returned by the `route` function.
pub type Route = (&'static str, &'static str, Box<dyn Fn(&Message, SessionID) -> Result<(), MessageRejectErrorEnum> + Send>);

/// Returns the begin string, message type, and route function for `AllocationInstruction`.
pub fn route(router: RouteOut) -> Route {
    let r = move |msg: &Message, session_id: SessionID| -> Result<(), MessageRejectErrorEnum> {
        router(AllocationInstruction::from_message(msg.clone()), session_id)
    };
    ("FIX.4.4", "J", Box::new(r))
}
